/* Source-attributed daily library + online headlines. No AI generation is claimed. */
const Library=(()=>{
 const key=Profiles.key('library');let pack=BUNDLED_MATERIALS;let drafts={};try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){validate(saved.pack);pack=saved.pack;drafts=saved.drafts||{};}}catch(e){}
 function day(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
 function safeLink(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:'';}catch(e){return '';}}
 function validate(p){if(!p||p.version!==1||!Array.isArray(p.materials)||p.materials.length<1||p.materials.length>1000)throw Error('素材格式无效');const ids=new Set();for(const m of p.materials){if(!m||typeof m.id!=='string'||ids.has(m.id))throw Error('素材标识无效');ids.add(m.id);for(const key of ['title','theme','publisher','sourceUrl','sourcePublished','checkedAt','chinese','translation','paragraph','paragraphTranslation','pattern','prompt','sample','kind','note'])if(typeof m[key]!=='string'||m[key].length>10000)throw Error('素材字段无效');if(!Array.isArray(m.checks)||!Array.isArray(m.keywords)||[...m.checks,...m.keywords].some(v=>typeof v!=='string'||v.length>1000))throw Error('素材检查项无效');if(m.sourceUrl&&!safeLink(m.sourceUrl))throw Error('来源链接无效');}return p;}
 function persist(){try{localStorage.setItem(key,JSON.stringify({pack,drafts}));}catch(e){const status=document.getElementById('feedStatus');if(status)status.textContent='素材保存失败，请导出学习备份';}}
 function today(){const dated=pack.materials.find(m=>m.day===day());if(dated)return dated;const n=Math.floor((Date.parse(day()+'T00:00:00+08:00')-Date.parse('2026-10-08T00:00:00+08:00'))/86400000);return pack.materials[((n%pack.materials.length)+pack.materials.length)%pack.materials.length];}
 async function refresh(){const status=document.getElementById('feedStatus');if(status)status.textContent='正在联网核对素材包…';try{const res=await fetch('./daily-feed.json',{cache:'no-store',signal:AbortSignal.timeout(7000)});if(!res.ok)throw Error('HTTP '+res.status);const next=validate(await res.json());pack=next;persist();render();const currentStatus=document.getElementById('feedStatus');if(currentStatus)currentStatus.textContent='素材包版本日期 '+pack.updatedAt+' · 核对 '+new Date().toLocaleString('zh-CN')+'（不表示今天有新增）';}catch(e){if(status)status.textContent='更新未完成，使用已保存素材 · '+e.message;}await Promise.allSettled([news(),delivery()]);}
 function sourceHTML(m){return `<p class="meta">${esc(m.kind)} · ${esc(m.publisher)} · 来源日期 ${esc(m.sourcePublished)}<br>核验 ${esc(m.checkedAt)} · ${esc(m.note)} ${safeLink(m.sourceUrl)?`<a href="${esc(safeLink(m.sourceUrl))}" target="_blank" rel="noopener noreferrer">查看来源</a>`:''}</p>`;}
 function pin(s){if(!s.material)s.material=JSON.parse(JSON.stringify(today()));return s.material;}
 function render(){const node=document.getElementById('dailyLibrary');if(!node)return;const selected=node.dataset.selected;const m=pack.materials.find(x=>x.id===selected)||today();const value=drafts[m.id]||'';node.innerHTML=`<div class="row spaced"><div><span class="eyebrow">${day()} · 今日表达</span><h2>${esc(m.title)}</h2></div><button id="refreshLibrary">联网更新</button></div><p>当前 ${pack.materials.length} 组练习 · 新闻主题关联题与来源改编题分别标注。</p><label for="materialPick">选择主题</label><select id="materialPick">${pack.materials.map(x=>`<option value="${esc(x.id)}" ${x.id===m.id?'selected':''}>${esc(x.title)} · ${esc(x.theme)}</option>`).join('')}</select>${sourceHTML(m)}<div class="example">${esc(m.chinese)}</div><details><summary>参考短译与句式</summary><p>${esc(m.translation)}</p><p><b>${esc(m.pattern)}</b></p><p>关键词：${m.keywords.map(esc).join(' · ')}</p></details><details><summary>段落翻译拓展（不计入 20 分钟）</summary><p>${esc(m.paragraph)}</p><label for="paragraphDraft">你的段落译文</label><textarea id="paragraphDraft" maxlength="20000"></textarea><details><summary>查看参考段落译文</summary><p>${esc(m.paragraphTranslation)}</p></details></details><p class="meta">20 分钟训练采用本轮开始时的素材快照，更新不会替换已有题目或作答。</p><p id="feedStatus" role="status">素材包日期 ${esc(pack.updatedAt)} · 已保存在此设备</p><p id="cloudStatus" role="status">正在核对服务器更新状态…</p><h3>六级主题新闻线索</h3><p class="meta">来源：人民网文化、教育、科技栏目，BBC News 教育与科学环境，WHO。仅保留近七天与备考主题相关的条目；规则筛选不代表命题预测。</p><div id="newsList">正在获取…</div>`;document.getElementById('materialPick').onchange=e=>{node.dataset.selected=e.target.value;render();news();delivery();};document.getElementById('refreshLibrary').onclick=refresh;const el=document.getElementById('paragraphDraft');el.value=value;el.oninput=()=>{drafts[m.id]=el.value;persist();};}
 async function news(){const node=document.getElementById('newsList');if(!node)return;let data=null,failed=false;try{const res=await fetch('./api/news',{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error('HTTP '+res.status);data=await res.json();if(!Array.isArray(data.items)||!data.items.length)throw Error('暂无可用条目');try{localStorage.setItem(Profiles.key('news'),JSON.stringify(data));}catch(e){}}catch(e){failed=true;try{data=JSON.parse(localStorage.getItem(Profiles.key('news'))||'null');}catch(e){}}if(!data?.items?.length){node.innerHTML='<p class="meta">实时来源暂不可用；审核素材仍可离线学习。需要使用包含联网服务的服务器，纯静态托管不能提供此接口。</p>';return;}node.innerHTML=`<p class="meta">${failed||data.status==='stale'?'更新失败，显示旧缓存':'已获取来源消息'} · 抓取 ${esc(data.fetchedAt||'未知')}</p><ul class="checks">${data.items.slice(0,12).map(x=>`<li>${safeLink(x.url)?`<a href="${esc(safeLink(x.url))}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a>`:esc(x.title)}<br><small>${esc(x.publisher)} · 原文日期 ${esc(x.published||'未标注')} · ${esc(x.theme||'主题未标注')}<br>${esc(x.reason||'')}</small></li>`).join('')}</ul>`;}
 async function delivery(){const node=document.getElementById('cloudStatus');if(!node)return;try{const res=await fetch('./api/library/status',{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error('不可用');const info=await res.json();node.textContent=(['updated','partial'].includes(info.state)&&info.lastSuccessDay===info.today?'服务器今日主题素材已发布':'服务器尚未完成今日更新')+' · 最近成功 '+(info.lastSuccess||'暂无')+' · '+info.mode+(info.errors?.length?' · 部分来源不可用，保留已有练习':'');}catch(e){node.textContent='服务器更新状态无法核对 · 已下载内容仍可离线学习';}}
 function backup(){return {pack,drafts};}function restore(data){if(!data)return;validate(data.pack);if(!data.drafts||typeof data.drafts!=='object'||Object.values(data.drafts).some(v=>typeof v!=='string'||v.length>20000))throw Error('段落草稿无效');pack=data.pack;drafts=data.drafts;persist();render();}
 return {day,today,pin,sourceHTML,validate,render,refresh,news,backup,restore};
})();
